/* ============================================================
   NEONE Movie Insights — app.js
   ============================================================
   重要安全提醒（請詳讀）：
   下面的 TMDB_API_KEY 會被瀏覽器完整下載並執行，任何人只要在瀏覽器
   按右鍵「檢視原始碼」或打開開發者工具的 Network 分頁，都看得到這把金鑰。
   這是純前端靜態網站（沒有後端伺服器）的固有限制，不是這份程式碼寫錯，
   而是「JS 一定會被使用者的瀏覽器完整下載執行」這件事本身決定的。

   這把金鑰目前能造成的影響：
   - 有心人士可以複製這把金鑰去發送請求，消耗你在 TMDB 的請求額度。
   - TMDB 的 API 金鑰目前不支援像 Google Maps API 金鑰那樣「綁定網域」
     的白名單限制，所以沒有辦法讓這把金鑰「只能在你的網域上使用」。

   如果之後想徹底解決（把金鑰真正藏起來，瀏覽器完全看不到），做法是：
   在 TMDB 和瀏覽器中間加一層你自己控制的伺服器（例如 Cloudflare Workers、
   Vercel Serverless Function 等），瀏覽器改成呼叫「你自己的網址」，
   由那層伺服器代為夾帶金鑰去呼叫 TMDB，金鑰只存在伺服器環境變數裡，
   不會出現在任何瀏覽器下載得到的檔案中。這是一個額外的基礎設施決定，
   這次先不動，只在這裡留下清楚的說明，之後想做可以再回來加。
   ============================================================ */

const TMDB_API_KEY = 'f1baea1a64768c2ace8585a66ad8fbdc';

const langDict = { ko: "韓語", ja: "日語", en: "英語", zh: "華語", cn: "華語", hi: "印度語", th: "泰語", vi: "越語", fr: "法語", de: "德語", es: "西班牙語", it: "義大利語", ru: "俄語" };

const arcLines = document.querySelectorAll('.arc-line-el');
const arcFills = document.querySelectorAll('.arc-fill-el');

function playArcSweep() {
  arcFills.forEach(el => el.classList.add('opacity-0'));
  arcLines.forEach(el => el.classList.remove('animate-draw-arc'));
  void arcLines[0].offsetWidth;
  requestAnimationFrame(() => {
    arcLines.forEach(el => el.classList.add('animate-draw-arc'));
    arcFills.forEach(el => el.classList.remove('opacity-0'));
  });
}

/* =========================================================
   進場動畫：5 個階段
   階段1 (0ms)    : 畫面淨空，僅背景
   階段2 (500ms)  : 弧線從左下劃至右下，底層藍色光暈同步浮現
   階段3 (1200ms) : Fade in 'Build Faster' 與 'Movie Insights'
   階段4 (2400ms) : Fade in 'With' 與 'NEONE'
   階段5 (3200ms) : Fade in 左上角 Logo、偏好篩選、副標題、請推薦電影 Button

   音效改成只在「使用者點擊請推薦我電影」時播放（見 recommendBtn 的 click handler），
   不再跟開場動畫綁在一起——因為開場動畫是頁面一載入就自動播放，瀏覽器的自動播放政策
   一定會擋掉這個時間點的有聲音訊，靠任何前端手法都無法保證音效準時播出；而按下按鈕
   是使用者真正的互動行為，音效在這個時間點播放才會穩定、不會被擋。
   ========================================================= */
const sfxWhoosh = new Audio('data:audio/mpeg;base64,');
const sfxDing = new Audio('data:audio/mpeg;base64,');
sfxWhoosh.volume = 0.55;
sfxDing.volume = 0.5;
sfxWhoosh.preload = 'auto';
sfxDing.preload = 'auto';

function playSfx(audioEl) {
  audioEl.currentTime = 0;
  const p = audioEl.play();
  if (p && p.catch) p.catch(() => {});
}

// 統一的淡入顯示／隱藏：讓偏好篩選卡片、電影資訊卡都用同一套 800ms fade-in
function showWithFade(el) {
  el.classList.remove('hidden');
  el.classList.add('opacity-0');
  void el.offsetWidth;
  requestAnimationFrame(() => {
    el.classList.remove('opacity-0');
  });
}
function hideElement(el) {
  el.classList.add('hidden');
}

window.addEventListener('DOMContentLoaded', () => {
  setTimeout(() => {
    playArcSweep();
  }, 500);

  setTimeout(() => {
    document.getElementById('part-build-faster').classList.remove('opacity-0');
    document.getElementById('part-movie-insights').classList.remove('opacity-0');
  }, 1200);

  setTimeout(() => {
    document.getElementById('part-with').classList.remove('opacity-0');
    document.getElementById('part-neone').classList.remove('opacity-0');
  }, 2400);

  setTimeout(() => {
    document.getElementById('header-logo').classList.remove('opacity-0');
    document.getElementById('header-filter').classList.remove('opacity-0');
    document.getElementById('hero-desc').classList.remove('opacity-0');
    document.getElementById('recommend-btn-container').classList.remove('opacity-0');
  }, 3200);
});

const headerLogo = document.getElementById('header-logo');
const recommendBtn = document.getElementById('recommend-btn');
const btnText = document.getElementById('btn-text');
const btnIcon = document.getElementById('btn-icon');
const heroState = document.getElementById('hero-state');
const resultCard = document.getElementById('result-card');
const srAnnouncement = document.getElementById('sr-announcement');

const headerFilter = document.getElementById('header-filter');
const filterPanel = document.getElementById('filter-panel');
const resetFilter = document.getElementById('reset-filter');

const moviePoster = document.getElementById('movie-poster');
// 海報載入失敗時的備用圖（原本是 HTML 裡的 inline onerror 屬性，
// 移到這裡統一用 addEventListener 註冊，讓 CSP 的 script-src 不需要
// 為了這一行放寬 'unsafe-inline'，所有互動邏輯都集中在這支檔案管理）
moviePoster.addEventListener('error', function onPosterError() {
  moviePoster.removeEventListener('error', onPosterError);
  moviePoster.src = 'https://placehold.co/400x600/181c25/38bdf8?text=Poster+Unavailable';
});
const movieTitle = document.getElementById('movie-title');
const movieOriginalTitle = document.getElementById('movie-original-title');
const movieYear = document.getElementById('movie-year');
const movieRating = document.getElementById('movie-rating');
const movieLangTag = document.getElementById('movie-lang-tag');
const movieOverview = document.getElementById('movie-overview');
const overviewToggle = document.getElementById('overview-toggle');
const movieCast = document.getElementById('movie-cast');

// 設定劇情簡介文字：超過 5 行才顯示「顯示完整劇情」按鈕，短文字則不會多此一舉
function setOverviewText(text) {
  movieOverview.textContent = text;
  movieOverview.classList.remove('is-expanded');
  overviewToggle.textContent = '顯示完整劇情';
  overviewToggle.classList.add('hidden');
  requestAnimationFrame(() => {
    if (movieOverview.scrollHeight > movieOverview.clientHeight + 1) {
      overviewToggle.classList.remove('hidden');
    }
  });
}
overviewToggle.addEventListener('click', () => {
  const expanded = movieOverview.classList.toggle('is-expanded');
  overviewToggle.textContent = expanded ? '收合劇情簡介' : '顯示完整劇情';
});
const movieDirector = document.getElementById('movie-director');

headerLogo.addEventListener('click', (e) => {
  e.preventDefault();
  resultCard.classList.add('hidden');
  filterPanel.classList.add('hidden');
  heroState.classList.remove('hidden');
  btnText.textContent = "請推薦我電影";
  btnIcon.className = "fa-solid fa-wand-magic-sparkles text-cyan-600";
});

// 自訂下拉選單邏輯（電影類型／語系）
const selectedValues = { genre: '', lang: '' };

document.querySelectorAll('.custom-select').forEach((wrapper) => {
  const key = wrapper.dataset.select;
  const trigger = wrapper.querySelector('.select-trigger');
  const label = wrapper.querySelector('.select-label');
  const optionsPanel = wrapper.querySelector('.select-options');
  const options = wrapper.querySelectorAll('.select-option');

  trigger.addEventListener('click', (e) => {
    e.stopPropagation();
    const isOpen = wrapper.classList.contains('is-open');
    document.querySelectorAll('.custom-select.is-open').forEach((el) => {
      el.classList.remove('is-open');
      el.querySelector('.select-options').classList.add('hidden');
    });
    if (!isOpen) {
      wrapper.classList.add('is-open');
      optionsPanel.classList.remove('hidden');
    }
  });

  options.forEach((option) => {
    option.addEventListener('click', (e) => {
      e.stopPropagation();
      selectedValues[key] = option.dataset.value;
      label.textContent = option.textContent;
      options.forEach((o) => o.classList.remove('is-selected'));
      option.classList.add('is-selected');
      wrapper.classList.remove('is-open');
      optionsPanel.classList.add('hidden');
    });
  });
});

// 記住「開啟偏好篩選之前」畫面上原本顯示的是首頁標題還是已經抽到的電影結果，
// 這樣如果使用者只是點開篩選看一下、沒有實際套用就關掉，畫面能還原成原本的樣子，
// 而不是被重置回首頁標題。
let resultCardWasVisibleBeforeFilter = false;

function closeFilterPanel() {
  hideElement(filterPanel);
  if (resultCardWasVisibleBeforeFilter) {
    showWithFade(resultCard);
  } else {
    heroState.classList.remove('hidden');
  }
  headerFilter.setAttribute('aria-expanded', 'false');
}

document.addEventListener('click', (e) => {
  document.querySelectorAll('.custom-select.is-open').forEach((el) => {
    el.classList.remove('is-open');
    el.querySelector('.select-options').classList.add('hidden');
  });

  // 點擊篩選卡片以外的空白處也會關閉篩選面板（但不要跟「偏好篩選」按鈕自己的 toggle 邏輯衝突）
  const isFilterOpen = !filterPanel.classList.contains('hidden');
  if (isFilterOpen && !filterPanel.contains(e.target) && !headerFilter.contains(e.target)) {
    closeFilterPanel();
  }
});

// 點擊「偏好篩選」：以篩選卡片取代首頁標題區（800ms fade-in）
headerFilter.addEventListener('click', (e) => {
  e.stopPropagation(); // 避免立刻被上面的「點擊空白處關閉」邏輯誤判成點在外部
  const willOpen = filterPanel.classList.contains('hidden');
  if (willOpen) {
    resultCardWasVisibleBeforeFilter = !resultCard.classList.contains('hidden');
    hideElement(heroState);
    hideElement(resultCard);
    showWithFade(filterPanel);
    headerFilter.setAttribute('aria-expanded', 'true');
  } else {
    closeFilterPanel();
  }
});

resetFilter.addEventListener('click', () => {
  selectedValues.genre = '';
  selectedValues.lang = '';
  document.querySelectorAll('.custom-select').forEach((wrapper) => {
    const label = wrapper.querySelector('.select-label');
    const options = wrapper.querySelectorAll('.select-option');
    options.forEach((o) => o.classList.toggle('is-selected', o.dataset.value === ''));
    const defaultOption = wrapper.querySelector('.select-option[data-value=""]');
    if (defaultOption) label.textContent = defaultOption.textContent;
  });
  srAnnouncement.textContent = '篩選條件已重置';
});

// 帶逾時保護的 fetch：某些網路環境下連線可能卡住（已送出但一直沒有回應，也不會自然噴錯），
// 導致畫面永遠停在「抽選中」。這裡用 AbortController 設定 10 秒逾時，
// 超過就主動中止並丟出錯誤，讓下面既有的 catch／錯誤提示邏輯可以正常接手。
function fetchWithTimeout(url, ms = 10000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  return fetch(url, { signal: controller.signal }).finally(() => clearTimeout(timer));
}

async function fetchRandomMovieFromTMDb() {
  const genre = selectedValues.genre;
  const lang = selectedValues.lang;

  let baseUrl = `https://api.themoviedb.org/3/discover/movie?api_key=${TMDB_API_KEY}&language=zh-TW&sort_by=popularity.desc&vote_count.gte=50&include_adult=false`;

  if (genre) baseUrl += `&with_genres=${genre}`;
  if (lang) baseUrl += `&with_original_language=${lang}`;

  try {
    const res1 = await fetchWithTimeout(`${baseUrl}&page=1`);
    const data1 = await res1.json();

    if (!data1.results || data1.results.length === 0) {
      alert("沒有找到符合該條件的電影，請放寬篩選條件！");
      return null;
    }

    const totalPages = Math.min(data1.total_pages || 1, 30);
    const randomPage = Math.floor(Math.random() * totalPages) + 1;

    const res2 = await fetchWithTimeout(`${baseUrl}&page=${randomPage}`);
    const data2 = await res2.json();

    const validMovies = (data2.results || []).filter(m => m.poster_path && m.overview);
    if (validMovies.length === 0) return data1.results[0];

    const randomIndex = Math.floor(Math.random() * validMovies.length);
    return validMovies[randomIndex];
  } catch (error) {
    console.error("TMDb API Error:", error);
    alert("無法連線至 TMDb API，請檢查網路連線！");
    return null;
  }
}

async function fetchMovieCredits(movieId) {
  try {
    const res = await fetchWithTimeout(`https://api.themoviedb.org/3/movie/${movieId}/credits?api_key=${TMDB_API_KEY}&language=zh-TW`);
    const data = await res.json();
    const names = (data.cast || []).slice(0, 3).map(c => c.name);
    const director = (data.crew || []).find(c => c.job === 'Director');
    return {
      cast: names.length ? names.join('、') : '暫無資料',
      director: director ? director.name : '暫無資料'
    };
  } catch (error) {
    return { cast: '暫無資料', director: '暫無資料' };
  }
}

// 等新海報圖片真的下載完成才 resolve，避免卡片淡入時畫面還停在上一部海報；
// 加上 6 秒安全逾時──某些網路環境下圖片可能一直不觸發 load/error，
// 逾時就強制繼續，避免畫面永遠卡在「抽選中」不會往下走。
function loadPosterImage(src) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = () => {
      if (settled) return;
      settled = true;
      moviePoster.removeEventListener('load', finish);
      moviePoster.removeEventListener('error', finish);
      clearTimeout(timer);
      resolve();
    };
    const timer = setTimeout(finish, 6000);
    moviePoster.addEventListener('load', finish, { once: true });
    moviePoster.addEventListener('error', finish, { once: true });
    moviePoster.src = src;
  });
}

recommendBtn.addEventListener('click', async () => {
  heroState.classList.add('hidden');
  filterPanel.classList.add('hidden');
  resultCard.classList.add('hidden');
  moviePoster.removeAttribute('src'); // 立刻清掉上一部海報，避免殘留畫面

  playArcSweep();
  playSfx(sfxWhoosh);

  btnText.textContent = "抽選中...";
  btnIcon.className = "fa-solid fa-spinner fa-spin text-cyan-600";
  recommendBtn.disabled = true;

  const [movie] = await Promise.all([
    fetchRandomMovieFromTMDb(),
    new Promise(resolve => setTimeout(resolve, 1300))
  ]);

  if (movie) {
    const [credits] = await Promise.all([
      fetchMovieCredits(movie.id),
      loadPosterImage(`https://image.tmdb.org/t/p/w500${movie.poster_path}`)
    ]);

    movieTitle.textContent = movie.title || movie.original_title;
    movieOriginalTitle.textContent = movie.original_title !== movie.title ? movie.original_title : '';
    movieYear.textContent = movie.release_date ? `(${movie.release_date.split('-')[0]})` : '';
    movieRating.textContent = movie.vote_average ? movie.vote_average.toFixed(1) : 'N/A';

    movieLangTag.textContent = langDict[movie.original_language] || movie.original_language.toUpperCase();
    setOverviewText(movie.overview || "此電影暫無中文劇情摘要說明。");
    movieCast.textContent = credits.cast;
    movieDirector.textContent = credits.director;

    showWithFade(resultCard);
    playSfx(sfxDing);
    srAnnouncement.textContent = `已為你推薦電影：${movieTitle.textContent}`;

    btnText.textContent = "再換一部 🎲";
    btnIcon.className = "fa-solid fa-rotate-right text-cyan-600";
  } else {
    heroState.classList.remove('hidden');
    btnText.textContent = "請推薦我電影";
    btnIcon.className = "fa-solid fa-wand-magic-sparkles text-cyan-600";
  }

  recommendBtn.disabled = false;
});
